<?php use App\Core\DB; $groups=[];foreach($def['fields'] as $key=>$field)$groups[$field['group']??($module==='products'?'Basic Details':'Details')][$key]=$field;if($module==='products'){$groups['Specifications']=[];$ordered=[];foreach(['Basic Details','Classification','Images','Specifications','Links & Buttons','SEO','Publishing'] as $name)if(isset($groups[$name]))$ordered[$name]=$groups[$name];$groups=$ordered;}?>
<div class="page-heading"><div><a class="back-link" href="<?=e(cms_url('/admin/'.$module))?>">← <?=e($def['label'])?></a><h1><?=$id?e($record['title']??$record['name']??'Edit record'):'Create something new'?></h1><p><?=$id?'Last updated '.e(ist_datetime($record['updated_at'])):'Start with the details below. You can keep your work as a draft.'?></p></div><?php if($id&&in_array($module,['pages','products'],true)):?><a class="button secondary" href="<?=e(cms_url('/admin/preview/'.$module.'/'.$id))?>" target="_blank" rel="noopener">Preview ↗</a><?php endif?></div>
<?php if($errors):?><div class="notice error" role="alert"><strong>We couldn't save these changes.</strong><ul><?php foreach($errors as $key=>$error):?><li><?=e(($def['fields'][$key]['label']??'Record').': '.$error)?></li><?php endforeach?></ul></div><?php endif?>
<form class="editor-form panel" method="post" data-unsaved><?=csrf_field()?><input type="hidden" name="_version" value="<?=e($version)?>"><div class="editor-tabs" role="tablist"><?php foreach(array_keys($groups) as $i=>$group):?><button type="button" role="tab" class="<?=$i===0?'active':''?>" data-tab="tab-<?=$i?>" aria-selected="<?=$i===0?'true':'false'?>"><?=e($group)?></button><?php endforeach?></div><?php foreach($groups as $group=>$fields):$i=array_search($group,array_keys($groups));?><section class="editor-section" id="tab-<?=$i?>" role="tabpanel" aria-label="<?=e($group)?>"><h2><?=e($group)?></h2><div class="form-grid"><?php foreach($fields as $key=>$field)cms_view('admin/field',compact('key','field','record','errors'));?></div><?php cms_view('admin/product-related',compact('module','group','id'));?></section><?php endforeach?><div class="editor-actions"><a class="button secondary" href="<?=e(cms_url('/admin/'.$module))?>">Cancel</a><div class="actions"><?php if(!empty($def['drafts'])):?><button class="button secondary" name="intent" value="draft">Save draft</button><?php if(($record['status']??'')==='published'):?><button class="button secondary" name="intent" value="unpublish">Unpublish</button><?php endif?><button class="button" name="intent" value="publish">Publish changes →</button><?php else:?><button class="button" name="intent" value="save">Save changes →</button><?php endif?></div></div></form>
<?php if($id):$links=match($module){'pages'=>[['/admin/homepage?page_id='.$id,'Edit page sections']],'page_sections'=>[['/admin/hero_slides?section_id='.$id,'Manage hero slides'],['/admin/section_items?section_id='.$id,'Manage section items'],['/admin/preview/pages/'.$record['page_id'],'Preview page']],'products'=>[['/admin/product_images?product_id='.$id,'Additional images'],['/admin/product_specifications?product_id='.$id,'Specifications']],'navigation_items'=>[['/admin/navigation_items?parent_id='.$id,'Nested menu items'],['/admin/mega_menu_groups?navigation_item_id='.$id,'Mega menu groups']],'mega_menu_groups'=>[['/admin/mega_menu_items?group_id='.$id,'Choose manual links']],'gallery_albums'=>[['/admin/gallery_items?album_id='.$id,'Album items']],'footer_columns'=>[['/admin/footer_menu_items?column_id='.$id,'Column links']],'enquiries'=>[['/admin/enquiry_notes?enquiry_id='.$id,'Internal notes']],default=>[]};if($links):?><section class="panel related-tools"><h2>Continue editing</h2><div class="actions"><?php foreach($links as [$href,$label]):?><a class="button secondary" href="<?=e(cms_url($href))?>"><?=e($label)?> →</a><?php endforeach?></div></section><?php endif?><?php if($module==='media_files'):$uses=App\Services\Media::usage($id);?><section class="panel related-tools"><h2>Where this file is used</h2><p><?=e($uses?implode(', ',$uses):'No current content references this file.')?></p><label class="upload-inline">Replace this file<input type="file" data-replace-media="<?=$id?>" hidden></label></section><?php endif?><?php endif?>
<?php if($revisions):?><details class="panel revision-panel"><summary>Revision history · <?=count($revisions)?> saved versions</summary><?php foreach($revisions as $revision):?><form class="revision-row" method="post" action="<?=e(cms_url('/admin/'.$module.'/'.$id.'/restore'))?>"><?=csrf_field()?><input type="hidden" name="revision_id" value="<?=$revision['id']?>"><span><?=e(ist_datetime($revision['created_at']))?> · <?=e($revision['name']??'Former administrator')?></span><button class="button secondary tiny">Restore as draft</button></form><?php endforeach?></details><?php endif?>
